package com.koios.game.arpg;
import java.util.*;import com.koios.game.model.Location;import com.koios.game.model.mob.*;import com.koios.game.model.player.Player;import com.koios.game.model.item.Item;import com.koios.game.map.MapRegion;import com.koios.game.map.path.StraightPathFinder;
/** Owned, stationary private-base services; paid purchases never fall back to bank/mailbox. */
public final class HubServices {
 public static final int QUARTERMASTER=15014,GEMCUTTER=15015;
 private static final Map<Player,List<ServiceMob>> OWNED=new HashMap<>();
 private static final Map<Player,ServiceMob> PENDING=new HashMap<>();
 public static int template(int id){return id==QUARTERMASTER?519:id==GEMCUTTER?540:id;}
 public static List<ServiceMob> services(Player p){List<ServiceMob> list=OWNED.get(p);return list==null?Collections.emptyList():Collections.unmodifiableList(list);}
 public static List<ServiceMob> spawn(Player p,Location spawn,List<Location> fixtures){
  if(OWNED.containsKey(p))return services(p);List<ServiceMob> list=new ArrayList<>();
  try{for(int id:new int[]{QUARTERMASTER,GEMCUTTER}){Location selected=null;for(Location at:MapRuns.reachable(spawn,8)){if(Location.getManhattanDistance(spawn,at)<4||MapRegion.getObject(at.getX(),at.getY(),0)!=null||!clearsFixtures(at,fixtures))continue;boolean fits=true;for(ServiceMob prior:list)if(Location.getManhattanDistance(prior.getLocation(),at)<4)fits=false;boolean approach=false;for(Location near:MapRuns.reachable(at,1))if(!near.equals(at)&&MapRegion.getObject(near.getX(),near.getY(),0)==null)approach=true;if(fits&&approach){selected=at;break;}}if(selected==null)throw new IllegalStateException("No reachable service anchor");ServiceMob mob=new ServiceMob(p,id,selected);MobManager.spawn(mob);list.add(mob);}OWNED.put(p,list);return services(p);}catch(RuntimeException ex){for(ServiceMob mob:list)remove(mob);throw ex;}
 }
 private static boolean clearsFixtures(Location at,List<Location> fixtures){for(Location anchor:fixtures){com.koios.game.map.RSObject object=MapRegion.getObject(anchor.getX(),anchor.getY(),0);if(object==null)return false;com.koios.game.map.ObjectDefinition definition=com.koios.game.map.ObjectDefinition.getById(object.getId());int width=definition.xLength,height=definition.yLength;if((object.getFace()&1)!=0){int swap=width;width=height;height=swap;}for(int x=0;x<width;x++)for(int y=0;y<height;y++)if(Math.abs(at.getX()-anchor.getX()-x)+Math.abs(at.getY()-anchor.getY()-y)<3)return false;}return true;}
 public static void cleanup(Player p){List<ServiceMob> list=OWNED.remove(p);if(list!=null)for(ServiceMob mob:list){mob.setVisible(false);remove(mob);}PENDING.remove(p);}
 private static void remove(ServiceMob mob){if(mob.getIndex()>=0&&MobManager.mobs[mob.getIndex()]==mob)MobManager.remove(mob);}
 private static void validate(Player p,ServiceMob mob){
  if(mob==null||mob.owner!=p||!services(p).contains(mob)||mob.getIndex()<0||MobManager.mobs[mob.getIndex()]!=mob||!MapRuns.isHome(p)||p.getZ()!=mob.getZ()||p.isDead()||p.isTeleporting()||p.isTrading()||p.getBankField().isBanking()||p.isPacketReadDisabled())throw new IllegalArgumentException("Visit your service NPC at home.");
  if(Tutorial.stage(p)<11)throw new IllegalArgumentException("Finish your guided introduction first.");
  if(Location.getManhattanDistance(p.getLocation(),mob.getLocation())>3||!StraightPathFinder.isInteractionPathClear(p.getLocation(),mob.getLocation()))throw new IllegalArgumentException("Move closer to the service NPC.");
 }
 private static ServiceMob find(Player p,int id){for(ServiceMob mob:services(p))if(mob.getId()==id)return mob;return null;}
 public static boolean interact(Player p,Mob mob){if(!(mob instanceof ServiceMob))return false;try{open(p,(ServiceMob)mob);}catch(IllegalArgumentException ex){p.sendMessage(ex.getMessage());}return true;}
 private static void open(Player p,ServiceMob mob){validate(p,mob);mob.setFaceIndex(p.getIndex(),true);p.setFaceIndex(mob.getIndex(),false);PENDING.put(p,mob);if(mob.getId()==QUARTERMASTER){String panel="supplies\nhub buy portals\t5 Portal Scrolls / 25 coins\nhub buy map\tTraining Map T1 / 25 coins\nhub buy wisdom\tWisdom Sigil / 20 coins\nguide\tBack to guide";p.getSession().send(new com.koios.network.out.impl.SendStringPacket(Base64.getEncoder().encodeToString(panel.getBytes(java.nio.charset.StandardCharsets.UTF_8)),65531));}else{p.sendMessage("Gem fusion: use two same-level active gems together.");p.sendMessage("The target gains one level. Fee: 25 x input level coins.");PrototypePanel.show(p,"craft");}}
 public static boolean handle(Player p,String input){if(!input.equals("hub")&&!input.startsWith("hub "))return false;try{String[] args=input.trim().split(" +");if(args.length==2&&args[1].equals("supplies"))open(p,find(p,QUARTERMASTER));else if(args.length==2&&args[1].equals("gems"))open(p,find(p,GEMCUTTER));else if(args.length==3&&args[1].equals("buy"))buy(p,args[2]);else throw new IllegalArgumentException("Visit your Quartermaster or Gemcutter.");}catch(IllegalArgumentException ex){p.sendMessage(ex.getMessage());}return true;}
 public static void buy(Player p,String offer){ServiceMob mob=PENDING.get(p);validate(p,mob);if(mob.getId()!=QUARTERMASTER)throw new IllegalArgumentException("Ask your Quartermaster for supplies.");Item item;int price;if(offer.equals("portals")){item=new Item(MapRuns.PORTAL_SCROLL,5);price=25;}else if(offer.equals("map")){item=MapRuns.map(1,0);price=25;}else if(offer.equals("wisdom")){item=new Item(CraftingCurrency.IDS[5]);price=20;}else throw new IllegalArgumentException("Unknown supply.");if(p.getInventory().getCount(995)<price)throw new IllegalArgumentException("You need "+price+" coins.");if(!p.getInventory().hasRoomFor(item))throw new IllegalArgumentException("Make inventory space first.");if(!p.getInventory().add(item))throw new IllegalArgumentException("Make inventory space first.");p.getInventory().remove(995,price);PENDING.remove(p);p.getSession().send(new com.koios.network.out.impl.SendStringPacket("close",65528));p.sendMessage("Purchased "+(offer.equals("map")?"a training map":offer.equals("wisdom")?"a Wisdom Sigil":"five Portal Scrolls")+" for "+price+" coins.");}
 public static final class ServiceMob extends Mob {public final Player owner;ServiceMob(Player owner,int id,Location at){super(id,at);this.owner=owner;}public boolean isAttackable(){return false;}public void update(){}public void death(){}}
 private HubServices(){}
}
